// Verifies the TypeScript port against output produced by the ORIGINAL Java classes
// (test/golden/golden.json, generated by test/golden/java/Golden.java).
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { PolishNotationFunction, MalformedFunction } from '../src/core/parser';
import { computeShot } from '../src/core/shot';
import { scenario } from './helpers';

const golden = JSON.parse(readFileSync(new URL('./golden/golden.json', import.meta.url), 'utf8'));
const PTS = [[-20, 0, 0], [-12.5, 1, 2], [-3, -2, 0.5], [0.5, 3, -1], [1, 0, 0], [4.2, -1.5, 2.2], [10, 5, -3], [24, -7, 1]];

const dec = (v: unknown): number => (v === 'NaN' ? NaN : v === 'Inf' ? Infinity : v === '-Inf' ? -Infinity : (v as number));
const close = (a: number, b: number, tol = 1e-9) => {
  if (Number.isNaN(b)) return Number.isNaN(a);
  if (!Number.isFinite(b)) return a === b;
  return Math.abs(a - b) <= tol * Math.max(1, Math.abs(b));
};

describe('parser/evaluator parity with Java', () => {
  for (const g of golden.eval) {
    it(`expr: ${g.expr}`, () => {
      if (!g.ok) { expect(() => new PolishNotationFunction(g.expr)).toThrow(MalformedFunction); return; }
      const f = new PolishNotationFunction(g.expr);
      PTS.forEach((p, i) => {
        const got = f.evaluateFunction(p[0], p[1], p[2]);
        expect(close(got, dec(g.vals[i])), `${g.expr} @${p} got ${got} want ${g.vals[i]}`).toBe(true);
      });
      expect(f.getStringFunction()).toBe(g.str);
    });
  }
});

describe('shot solver parity with Java', () => {
  for (const g of golden.shots) {
    const [mode, expr, turn, angle, kind] = g.case.split('|');
    it(`shot: ${g.case}`, () => {
      const { terrain, players } = scenario(kind);
      const t = Number(turn);
      const shot = computeShot(Number(mode), expr, terrain, players, t, players[t].team, Number(angle));
      if (kind === 'empty') {
        // no terrain involved -> must be bit-for-bit comparable (within float rounding of Math.sin etc.)
        expect(shot.numSteps).toBe(g.numSteps);
        expect(shot.playersHit.map((_, i) => [shot.playersHit[i], shot.soldiersHit[i], shot.soldierHitPosition[i]])).toEqual(g.hits);
      } else {
        // terrain edge rasterisation differs by <=1px from Java's anti-aliased image
        expect(Math.abs(shot.numSteps - g.numSteps)).toBeLessThanOrEqual(Math.max(8, g.numSteps * 0.01));
      }
      expect(close(shot.fireAngle, dec(g.fireAngle), 1e-9)).toBe(true);
      if (kind === 'empty') {
        expect(Math.abs(shot.lastX - dec(g.lastX))).toBeLessThan(1e-6);
        expect(Math.abs(shot.lastY - dec(g.lastY))).toBeLessThan(1e-6);
      }
      for (const [i, x, y] of g.samples as [number, number, number][]) {
        if (i >= shot.numSteps) continue;
        expect(close(shot.valuesX[i], dec(x), 1e-9), `x[${i}]`).toBe(true);
        expect(close(shot.valuesY[i], dec(y), 1e-8), `y[${i}] got ${shot.valuesY[i]} want ${y}`).toBe(true);
      }
    });
  }
});
